import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-script-task-map/ScriptTaskMapDemo.bpmn')
root = tree.getroot()

ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

# Collect all declared ids
all_ids = {el.get('id') for el in root.iter() if el.get('id')}
print('All IDs:', sorted(all_ids))

# Check all refs resolve
errors = []
proc = root.find('.//bpmn:process', ns)
for sf in proc.findall('bpmn:sequenceFlow', ns):
    src = sf.get('sourceRef'); tgt = sf.get('targetRef')
    if src not in all_ids: errors.append(f'sequenceFlow {sf.get(\"id\")} sourceRef {src} not found')
    if tgt not in all_ids: errors.append(f'sequenceFlow {sf.get(\"id\")} targetRef {tgt} not found')

# Check BPMNShape per node
shapes = {s.get('bpmnElement') for s in root.findall('.//bpmndi:BPMNShape', ns)}
flow_nodes = [e.get('id') for e in proc if e.get('id') and 'sequenceFlow' not in e.tag]
print('Flow nodes:', flow_nodes)
print('Shapes:', sorted(shapes))
for n in flow_nodes:
    if n not in shapes: errors.append(f'Node {n} has no BPMNShape')

# Check BPMNEdge per flow
edges = {e.get('bpmnElement') for e in root.findall('.//bpmndi:BPMNEdge', ns)}
flows = [sf.get('id') for sf in proc.findall('bpmn:sequenceFlow', ns)]
print('Flows:', flows)
print('Edges:', sorted(edges))
for f in flows:
    if f not in edges: errors.append(f'Flow {f} has no BPMNEdge')

# Check uipath:type child (not attribute) on mapping
for m in root.findall('.//uipath:mapping', ns):
    t = m.find('uipath:type', ns)
    if t is None: errors.append('uipath:mapping missing uipath:type child')
    elif m.get('type'): errors.append('uipath:mapping uses type= attribute instead of child element')

# Check scriptVersion
sv = root.find('.//uipath:scriptVersion', ns)
print('scriptVersion:', sv.get('value') if sv is not None else 'MISSING')

if errors:
    for e in errors: print('ERROR:', e)
    exit(1)
else:
    print('VALID - all checks passed')
"
